<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import Fields from './HostTrafficFields.vue'
import {hostDraft,hostPayload,hostBytes,hostModes,hostTrafficBytes} from './hostBilling'
const props=defineProps<{host:Record<string,any>,api:(p:string,m?:string,b?:any)=>Promise<any>}>(),emit=defineEmits<{close:[],changed:[]}>()
const stats=ref<Record<string,any>>(props.host.traffic??{}),draft=ref(hostDraft(stats.value)),busy=ref(false),dirty=ref(false),error=ref(''),notice=ref(''),restart=ref(false)
let alive=true,timer:ReturnType<typeof setTimeout>
async function load(){try{const s=await props.api('hosts/'+props.host.id+'/traffic');if(!alive)return;stats.value=s;if(!dirty.value){draft.value=hostDraft(s)}}catch(e){if(alive)error.value=String(e)}}
function schedule(){timer=setTimeout(async()=>{if(document.visibilityState!=='hidden')await load();if(alive)schedule()},30000)}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();dirty.value=false;await load();emit('changed')}catch(e){error.value=String(e)}finally{busy.value=false}}
function save(){void run(async()=>{await props.api('hosts/'+props.host.id+'/traffic','PUT',hostPayload(draft.value));notice.value='主机额度、周期和计费方式已保存。变更计费方向会按本周期 RX/TX 重算。'})}
function resetCycle(){if(!window.confirm('将本期已用量重置为 0，并从现在继续累计？网卡累计和历史数据保留。'))return;void run(async()=>{await props.api('hosts/'+props.host.id+'/traffic/calibrate','POST',{version:stats.value.version,used_bytes:0,restart_cycle:restart.value});notice.value='重置完成，后续按新增网卡字节继续累计。'})}
onMounted(()=>{void load();schedule()});onUnmounted(()=>{alive=false;clearTimeout(timer)})
</script>
<template><div class="modal-backdrop"><section class="modal host-traffic-modal" role="dialog" aria-modal="true" aria-label="主机流量"><div class="modal-heading"><div><h2>{{host.name}} · 主机流量</h2><p class="muted">系统网卡计量 · 套餐周期 · 独立于用户账单</p></div><button class="secondary" @click="emit('close')">关闭</button></div><div class="form-content"><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><div class="host-usage-grid"><article><small>本期计费已用</small><strong>{{hostTrafficBytes(stats.used_bytes)}}</strong><span>{{hostModes[stats.mode]}}</span></article><article><small>套餐实时剩余</small><strong>{{stats.quota_bytes?hostTrafficBytes(stats.remaining_bytes):'不限额'}}</strong><span :class="{error:!stats.fresh}">{{stats.fresh?'最新采样':'断报 / 等待采样'}} · {{stats.last_sample_at?new Date(stats.last_sample_at).toLocaleString():'尚未接入'}}</span></article><article><small>本周期原始传输</small><strong>↓ {{hostTrafficBytes(stats.period_rx)}} / ↑ {{hostTrafficBytes(stats.period_tx)}}</strong><span>RX {{hostBytes(stats.rx_rate)}}/s · TX {{hostBytes(stats.tx_rate)}}/s</span></article></div><p v-if="stats.quality==='gap'" class="notice">检测到重启、计量间断或状态重建，剩余值可能与运营商账单不一致。累计仍保留。缺口数 {{stats.gap_count}}。</p><p v-if="stats.next_reset_at" class="muted">下次重置：{{new Date(stats.next_reset_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}（北京时间）</p><form @submit.prevent="save" @input="dirty=true" @change="dirty=true"><Fields :draft="draft" :available="stats.interfaces_available"/><button class="primary" :disabled="busy">保存主机流量设置</button></form><details class="calibration-box"><summary>手动重置本期</summary><p class="muted">从现在重新计量本期，保留网卡累计和历史数据。</p><label class="check-label"><input v-model="restart" type="checkbox">同时从下个月设置日重新安排周期</label><button class="secondary" :disabled="busy" @click="resetCycle">重置本期</button></details></div></section></div></template>
<style scoped>.host-traffic-modal{width:min(532px,96vw)}.host-usage-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-bottom:14px}.host-usage-grid article{padding:10px;overflow-wrap:anywhere;border:1px solid var(--border);border-radius:8px;min-width:0}.host-usage-grid small,.host-usage-grid span{display:block;color:var(--muted);font-size:12px;line-height:1.55}.host-usage-grid strong{display:block;font-size:17px;margin:7px 0;overflow-wrap:anywhere}.calibration-box{border-top:1px solid var(--border);padding-top:12px;margin-top:16px}.calibration-box summary{cursor:pointer}.calibration-box label{margin:10px 0}@media(max-width:480px){.host-usage-grid{gap:5px}.host-usage-grid article{padding:6px}.host-usage-grid strong{font-size:13px;margin:5px 0}}</style>
